// Professional lightweight Chart.js-compatible stub for Zeno CRM.
// Supports line, doughnut, pie and horizontal bar charts with legends, ticks and grid lines.
(function (global) {
  function SimpleChart(ctx, config) {
    this.ctx = ctx;
    this.config = config || {};
    drawChart(this.ctx, this.config);
  }

  // Setup defaults object to allow app.js configuration (e.g. font family)
  SimpleChart.defaults = {
    font: {
      family: 'sans-serif'
    }
  };

  function getNumbers(arr) {
    return (arr || []).map(function (v) {
      var n = Number(v);
      return isNaN(n) ? 0 : n;
    });
  }

  function getFirstDataset(config) {
    var d = (config && config.data && config.data.datasets && config.data.datasets[0]) || {};
    return {
      data: getNumbers(d.data || []),
      backgroundColor: d.backgroundColor || '#4f46e5',
      borderColor: d.borderColor || '#4f46e5'
    };
  }

  function getDatasets(config) {
    var datasets = (config && config.data && config.data.datasets) || [];
    return datasets.map(function(d) {
      return {
        label: d.label || '',
        data: getNumbers(d.data || []),
        backgroundColor: d.backgroundColor || '#4f46e5',
        borderColor: d.borderColor || '#4f46e5'
      };
    });
  }

  function getFormatter(config, axis) {
    var callback = (config.options && config.options.scales && config.options.scales[axis] && config.options.scales[axis].ticks && config.options.scales[axis].ticks.callback);
    return function(v, index) {
      if (callback) return callback(v);
      return v;
    };
  }

  function drawChart(ctx, config) {
    if (!ctx || !config) return;
    var type = config.type || 'line';
    if (type === 'line') {
      drawLine(ctx, config);
    } else if (type === 'doughnut') {
      drawDoughnut(ctx, config);
    } else if (type === 'pie') {
      drawPie(ctx, config);
    } else if (type === 'bar') {
      drawBar(ctx, config);
    }
  }

  function getCanvasRect(ctx) {
    var c = ctx.canvas;
    var w = c.width;
    var h = c.height;
    if (!w || !h) {
      w = c.clientWidth || 400;
      h = c.clientHeight || 200;
      c.width = w;
      c.height = h;
    }
    return { w: w, h: h };
  }

  function drawLine(ctx, config) {
    var ds = getFirstDataset(config);
    var data = ds.data;
    var labels = (config && config.data && config.data.labels) || [];
    var rect = getCanvasRect(ctx);
    var w = rect.w;
    var h = rect.h;
    ctx.clearRect(0, 0, w, h);
    if (!data.length) return;

    var font = '10px ' + (SimpleChart.defaults.font.family || 'sans-serif');
    ctx.font = font;

    var max = Math.max.apply(null, data);
    if (max <= 0) max = 1;

    var left = 32;
    var right = 16;
    var top = 16;
    var bottom = 28;
    var innerW = w - left - right;
    var innerH = h - top - bottom;

    // Draw horizontal grid lines and Y-axis tick values
    ctx.strokeStyle = '#f3f4f6';
    ctx.lineWidth = 1;
    ctx.fillStyle = '#6b7280';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';

    var steps = 4;
    for (var s = 0; s <= steps; s++) {
      var val = (max / steps) * s;
      var y = top + innerH - (innerH * (s / steps));
      
      ctx.beginPath();
      ctx.moveTo(left, y);
      ctx.lineTo(w - right, y);
      ctx.stroke();

      ctx.fillText(Math.round(val), left - 6, y);
    }

    // Draw X-axis labels
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    data.forEach(function (v, i) {
      var label = labels[i] || '';
      var x = left + (innerW * (data.length === 1 ? 0.5 : i / (data.length - 1)));
      ctx.fillText(label, x, h - bottom + 6);
    });

    // Draw line
    ctx.strokeStyle = ds.borderColor;
    ctx.fillStyle = ds.backgroundColor;
    ctx.lineWidth = 2;
    ctx.beginPath();
    data.forEach(function (v, i) {
      var x = left + (innerW * (data.length === 1 ? 0.5 : i / (data.length - 1)));
      var y = top + innerH - (innerH * (v / max));
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    });
    ctx.stroke();

    // Fill area under the line
    ctx.lineTo(left + innerW, h - bottom);
    ctx.lineTo(left, h - bottom);
    ctx.closePath();
    ctx.fill();
    
    // Draw points
    ctx.fillStyle = ds.borderColor;
    data.forEach(function (v, i) {
      var x = left + (innerW * (data.length === 1 ? 0.5 : i / (data.length - 1)));
      var y = top + innerH - (innerH * (v / max));
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  function drawDoughnutOrPie(ctx, config, isDoughnut) {
    var ds = getFirstDataset(config);
    var data = ds.data;
    var labels = (config && config.data && config.data.labels) || [];
    var rect = getCanvasRect(ctx);
    var w = rect.w;
    var h = rect.h;
    ctx.clearRect(0, 0, w, h);
    if (!data.length) return;

    var total = data.reduce(function (a, b) { return a + b; }, 0);
    var colors = ds.backgroundColor;
    if (!Array.isArray(colors)) colors = [colors];

    var cx = w * 0.32;
    var cy = h / 2;
    var radius = Math.min(w * 0.55, h) / 2 - 12;
    var innerRadius = radius * 0.6;

    var start = -Math.PI / 2;
    for (var i = 0; i < data.length; i++) {
      var value = data[i];
      if (value <= 0) continue;
      var angle = total > 0 ? (value / total) * Math.PI * 2 : 0;
      var end = start + angle;
      var color = colors[i % colors.length];

      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, radius, start, end);
      ctx.closePath();
      ctx.fillStyle = color;
      ctx.fill();

      if (isDoughnut) {
        ctx.save();
        ctx.globalCompositeOperation = 'destination-out';
        ctx.beginPath();
        ctx.moveTo(cx, cy);
        ctx.arc(cx, cy, innerRadius, 0, Math.PI * 2);
        ctx.closePath();
        ctx.fill();
        ctx.restore();
      }

      start = end;
    }

    // Draw borders between slices
    start = -Math.PI / 2;
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1.5;
    for (var i = 0; i < data.length; i++) {
      var value = data[i];
      if (value <= 0) continue;
      var angle = total > 0 ? (value / total) * Math.PI * 2 : 0;
      var end = start + angle;
      
      ctx.beginPath();
      ctx.moveTo(cx, cy);
      ctx.arc(cx, cy, radius, start, end);
      ctx.closePath();
      ctx.stroke();
      
      start = end;
    }
    
    // Draw legend list
    var legendX = w * 0.60;
    var legendTop = Math.max(8, (h - data.length * 20) / 2);
    
    var font = '10px ' + (SimpleChart.defaults.font.family || 'sans-serif');
    ctx.font = font;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';

    for (var i = 0; i < data.length; i++) {
      var label = labels[i] || '';
      var value = data[i];
      var pct = total > 0 ? Math.round((value / total) * 100) : 0;
      var color = colors[i % colors.length];
      var y = legendTop + i * 20;

      ctx.fillStyle = color;
      ctx.fillRect(legendX, y - 5, 10, 10);
      
      ctx.strokeStyle = '#e5e7eb';
      ctx.lineWidth = 1;
      ctx.strokeRect(legendX, y - 5, 10, 10);

      ctx.fillStyle = '#374151';
      var text = label + ' (' + value + ' - ' + pct + '%)';
      ctx.fillText(text, legendX + 16, y);
    }
  }

  function drawDoughnut(ctx, config) {
    drawDoughnutOrPie(ctx, config, true);
  }

  function drawPie(ctx, config) {
    drawDoughnutOrPie(ctx, config, false);
  }

  function drawBar(ctx, config) {
    var datasets = getDatasets(config);
    var labels = (config && config.data && config.data.labels) || [];
    var rect = getCanvasRect(ctx);
    var w = rect.w;
    var h = rect.h;
    ctx.clearRect(0, 0, w, h);
    if (!datasets.length || !datasets[0].data.length) return;

    var font = '10px ' + (SimpleChart.defaults.font.family || 'sans-serif');
    ctx.font = font;

    var formatVal = getFormatter(config, 'y');

    var max = 0;
    datasets.forEach(function(ds) {
      var dsMax = Math.max.apply(null, ds.data);
      if (dsMax > max) max = dsMax;
    });
    if (max <= 0) max = 1;

    var top = 16;
    var bottom = 8;
    var left = 8;
    var right = 80;
    var innerW = w - left - right;
    var innerH = h - top - bottom;

    var numCategories = datasets[0].data.length;
    var categoryH = innerH / numCategories;

    for (var i = 0; i < numCategories; i++) {
      var label = labels[i] || '';
      var catY = top + i * categoryH;
      
      ctx.fillStyle = '#374151';
      ctx.font = 'bold 10px ' + (SimpleChart.defaults.font.family || 'sans-serif');
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText(label, left, catY);
      
      var numDatasets = datasets.length;
      var availableH = categoryH * 0.65;
      var barH = availableH / numDatasets;
      var barGap = 2;
      var startY = catY + 14;
      
      datasets.forEach(function(ds, dsIdx) {
        var value = ds.data[i] || 0;
        var barWidth = (value / max) * innerW;
        var y = startY + dsIdx * (barH + barGap);
        
        ctx.fillStyle = ds.backgroundColor;
        ctx.fillRect(left, y, barWidth, barH);
        
        ctx.fillStyle = '#4b5563';
        ctx.font = '9px ' + (SimpleChart.defaults.font.family || 'sans-serif');
        ctx.textAlign = 'left';
        ctx.textBaseline = 'middle';
        ctx.fillText(formatVal(value, i), left + barWidth + 6, y + barH/2);
      });
    }
  }

  global.Chart = SimpleChart;
  global.Chart.default = SimpleChart;
})(typeof window !== 'undefined' ? window : this);
